function chiffresS(t){ return String(t||"").replace(/\D/g,""); }
function eurS(n){ return (typeof n === "string") ? n : (Math.round(n*100)/100).toFixed(2).replace(".", ",").replace(",00","") + " €"; }
function slugS(t){ return String(t||"site").normalize("NFKD").replace(/[̀-ͯ]/g,"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"").slice(0,50) || "site"; }
