/* ----- couleurs : contraste AA garanti (même calcul que le générateur Python) ----- */
function rvbS(x){ return [1,3,5].map(function(i){ return parseInt(x.slice(i,i+2),16)/255; }); }
function hexS(c){ return "#" + c.map(function(v){ return ("0" + Math.max(0,Math.min(255,Math.round(v*255))).toString(16)).slice(-2); }).join(""); }
function lumS(x){ var c = rvbS(x).map(function(v){ return v <= 0.03928 ? v/12.92 : Math.pow((v+0.055)/1.055, 2.4); }); return 0.2126*c[0] + 0.7152*c[1] + 0.0722*c[2]; }
function contrasteS(a,b){ var l = [lumS(a), lumS(b)].sort(function(x,y){ return y-x; }); return (l[0]+0.05)/(l[1]+0.05); }
function melS(a,b,t){ var x = rvbS(a), y = rvbS(b); return hexS(x.map(function(v,i){ return v + (y[i]-v)*t; })); }
function texteCourt(v, n){ return String(v == null ? "" : v).replace(/[\u0000-\u001f]/g, " ").trim().slice(0, n || 400); }
